6	public class GameOfLife {
7	
8	    public Set<Cell> nextGeneration(Set<Cell> livingCells) {
9	        Set<Cell> nextGeneration = new HashSet<>();
10	        for (Cell cell : cellsThatCanChange(livingCells)) {
11	            if (isAliveNextGeneration(cell, livingCells)) {
12	                nextGeneration.add(cell);
13	            }
14	        }
15	        return nextGeneration;
16	    }
17	
18	    private Set<Cell> cellsThatCanChange(Set<Cell> livingCells) {
19	        Set<Cell> cells = new HashSet<>(livingCells);
20	        for (Cell cell : livingCells) {
21	            cells.addAll(cell.neighbours());
22	        }
23	        return cells;
24	    }
25	
26	    private boolean isAliveNextGeneration(Cell cell, Set<Cell> livingCells) {
27	        int livingNeighbours = countLivingNeighbours(cell, livingCells);
28	        if (livingCells.contains(cell)) {
29	            return survives(livingNeighbours);
30	        }
31	        return isBorn(livingNeighbours);
32	    }
33	
34	    private boolean survives(int livingNeighbours) {
35	        return livingNeighbours == 2 || livingNeighbours == 3;
36	    }
37	
38	    private boolean isBorn(int livingNeighbours) {
39	        return livingNeighbours == 3;
40	    }
41	
42	    private int countLivingNeighbours(Cell cell, Set<Cell> livingCells) {
43	        int count = 0;
44	        for (Cell neighbour : cell.neighbours()) {
45	            if (livingCells.contains(neighbour)) {
46	                count++;
47	            }
48	        }
49	        return count;
50	    }
51	}
